import{z as s,x as i,o as A,c as d,q as t,j as r,D as E,d as e,s as o,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"基本面因子从哪张表来","description":"","frontmatter":{"title":"基本面因子从哪张表来","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fundamental-factor-source.md","filePath":"quant/fundamental-factor-source.md","lastUpdated":1791063341000}'),p={name:"quant/fundamental-factor-source.md"};function c(u,a,h,m,F,C){const B=i("Mermaid");return A(),d("div",null,[a[2]||(a[2]=t('<h1 id="基本面因子从哪张表来" tabindex="-1">基本面因子从哪张表来 <a class="header-anchor" href="#基本面因子从哪张表来" aria-label="Permalink to &quot;基本面因子从哪张表来&quot;">​</a></h1><div class="epigraph"><p>价值取资产负债表的权益，盈利取利润表的流量，投资取资产或资本开支的变化，质量常取应计这条勾稽差；字段来源一错，因子名字就只是标签。</p><footer>—— 据 Fama and French, Journal of Financial Economics, 1993、2015；Hou, Xue and Zhang, Review of Financial Studies, 2015 整理</footer></div><p>到上一课<a href="/quant/industry-classification">行业分类与可比公司</a>为止，报表身份、PIT、幸存者、质量与预期都已具备。本课把常用基本面因子指回具体表与字段，当作本课程的索引，而不是再发明一套因子动物园。后课分部、租赁、少数股东只修正这些字段的口径，不改索引逻辑。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Fama–French 三因子的 HML 用账面权益 / 市值：账面来自资产负债表（Compustat 权益类字段），市值来自价量库，六月形成、账面滞后一年报。五因子把盈利（利润表，常为营业收入减费用后的经营利润一类口径）和投资（总资产增长或资本开支相关变化）加进来。Hou–Xue–Zhang 的 q 因子用盈利与投资，字段选择与 FF 不完全相同。缺口是：每个因子先写<strong>哪张表、哪个期间、哪个可用日期、哪个宇宙</strong>，再写分位断点。否则「复制 HML」只复制了名字。</p><p>质量/应计来自本课程早已钉死的 \\(NI-OCF\\) 或营运资本应计，不是五因子里的盈利。盈利高可以应计也高；来源不同，正交时才有意义。</p><h3 id="因子名不是会计恒等式" tabindex="-1">因子名不是会计恒等式 <a class="header-anchor" href="#因子名不是会计恒等式" aria-label="Permalink to &quot;因子名不是会计恒等式&quot;">​</a></h3><p>「盈利因子」可能用 ROE、ROIC、营业利润/账面，分母有时是权益、有时是资产。名字相同，表不同。本课要求管道里每个信号有一张来源卡：表、字段、缩放、PIT、行业调整与否。没有来源卡，后课无法修正租赁资本化或少数股东——因为不知道该改分子还是分母。</p><p><span class="marginnote">直觉类比：因子像菜名，来源卡像菜谱。同叫「鱼香肉丝」，各家做法不同——不问菜谱（哪张表、哪个字段、怎么缩放），照着名字点菜，端上来的可能不是你想吃的那盘。</span></p><p><span class="marginnote">French 数据库的 HML 说明明确写了 Compustat 账面与 CRSP 市值的匹配与滞后。复制因子等于复制这份说明，不是复制「低市净率」口诀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把主干信号按表归类。资产负债表时点：账面权益、总资产、净现金、递延税、商誉（用于调整）。利润表期间：收入、经营利润、税前/税后利润、减值与一次性项目。现金流量表期间：经营现金流、资本开支、分红与回购。价量库：市值、股本、退市回报。分析师库：共识与修正。每一项套用已有规则：可用日期、当时宇宙、股本口径、行业键。</p><p>形成日历与 Fama–French 对齐时：年报字段用 \\(t-1\\) 财年、在 \\(t\\) 年 6 月才进入；季报字段用各自可用日期。不要把季报盈利塞进「官方 HML 复制」还声称一致。</p><p><span class="marginnote">数字实例：一家公司 2025 财年（截至 2025-12-31）的账面权益，按 Fama–French 规则要到 2026 年 6 月才进入组合构造——中间近半年的「空窗」是刻意的 PIT 设计：报表要等审计与披露，用更早的数就等于偷看未来。</span></p>',14)),(A(),r(l,null,{default:E(()=>[o(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20BS%5B%22%E8%B5%84%E4%BA%A7%E8%B4%9F%E5%80%BA%E8%A1%A8%E6%97%B6%E7%82%B9%22%5D%20--%3E%20VAL%5B%22%E4%BB%B7%E5%80%BC%20HML%22%5D%0A%20%20IS%5B%22%E5%88%A9%E6%B6%A6%E8%A1%A8%E6%9C%9F%E9%97%B4%22%5D%20--%3E%20PROF%5B%22%E7%9B%88%E5%88%A9%22%5D%0A%20%20BS%20--%3E%20INV%5B%22%E6%8A%95%E8%B5%84%20%E8%B5%84%E4%BA%A7%E5%A2%9E%E9%95%BF%22%5D%0A%20%20CF%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%E9%87%8F%E8%A1%A8%22%5D%20--%3E%20ACC%5B%22%E5%BA%94%E8%AE%A1%E8%B4%A8%E9%87%8F%22%5D%0A%20%20PX%5B%22%E4%BB%B7%E9%87%8F%E4%B8%8E%E8%82%A1%E6%9C%AC%22%5D%20--%3E%20MV%5B%22%E5%B8%82%E5%80%BC%E5%88%86%E6%AF%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[e("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"因子收益对字段选择敏感，因为会计身份会把同一经济冲击记到不同表。并购抬高资产（投资）与商誉（账面），不一定抬高经营现金流（质量）。若投资因子用资产增长、价值用含商誉账面、质量用应计，三者同时被并购推动，看起来像三个 alpha，其实是一次收购会计。来源卡让你看见共线来自同一张表的同一事件。后课租赁入表会改资产与负债，从而同时改投资与杠杆；少数股东会改「归属母公司」的盈利与权益。索引先在，修正才有落点。",-1)),(A(),r(l,null,{default:E(()=>[o(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20MA%5B%22%E4%B8%80%E6%AC%A1%E5%B9%B6%E8%B4%AD%E4%BA%A4%E5%89%B2%22%5D%20--%3E%20A1%5B%22%E6%80%BB%E8%B5%84%E4%BA%A7%E8%86%A8%E8%83%80%22%5D%0A%20%20MA%20--%3E%20A2%5B%22%E5%95%86%E8%AA%89%E4%B8%8E%E5%90%88%E5%B9%B6%E8%B4%A6%E9%9D%A2%E5%85%A5%E8%A1%A8%22%5D%0A%20%20MA%20--%3E%20A3%5B%22%E5%B9%B6%E8%A1%A8%E5%88%A9%E6%B6%A6%E5%90%AB%E4%B8%80%E6%AC%A1%E6%80%A7%E9%A1%B9%E7%9B%AE%22%5D%0A%20%20A1%20--%3E%20F1%5B%22%E6%8A%95%E8%B5%84%E5%9B%A0%E5%AD%90%EF%BC%9A%E8%B5%84%E4%BA%A7%E5%A2%9E%E9%95%BF%E8%BD%AC%E6%AD%A3%22%5D%0A%20%20A2%20--%3E%20F2%5B%22%E4%BB%B7%E5%80%BC%E5%9B%A0%E5%AD%90%EF%BC%9A%E8%B4%A6%E9%9D%A2%E6%9D%83%E7%9B%8A%E6%8A%AC%E9%AB%98%22%5D%0A%20%20A3%20--%3E%20F3%5B%22%E7%9B%88%E5%88%A9%E5%9B%A0%E5%AD%90%EF%BC%9A%E5%8F%A3%E5%BE%84%E8%A2%AB%E6%89%B0%E5%8A%A8%22%5D%0A%20%20F1%20--%3E%20COL%5B%22%E4%B8%89%E4%B8%AA%E5%9B%A0%E5%AD%90%E5%90%8C%E5%90%91%E5%85%B1%E7%BA%BF%EF%BC%9A%E5%AE%9E%E4%B8%BA%E4%B8%80%E6%AC%A1%E6%94%B6%E8%B4%AD%E4%BC%9A%E8%AE%A1%22%5D%0A%20%20F2%20--%3E%20COL%0A%20%20F3%20--%3E%20COL%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：把三个因子同时有利当成「三重确认」。若它们被同一次并购的记账推动，这是共线不是确认——「多因子共振」可能只是同一个事件的三次回声，来源卡能告诉你回声来自哪张表。</span></p><p><span class="marginnote">本课不进入权重量化，也不把因子当成神经网络特征工程。对象仍是可交易的会计字段与当时信息集。</span></p><p>每条信号一张来源卡：表、字段、缩放、可用日期、宇宙、行业键、NCI 与税务口径。复制 French 库 HML 时，对照其账面定义与六月形成，不要用「低市净率」口诀替代。盈利与应计不要共用同一个利润字段还起两个名字。并购年、准则切换年在卡上留标记，便于后课租赁与商誉修正时知道该改哪一行，而不是再发明一个因子。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不估计全部异象清单，不比较哪些因子「还有效」。分部与地域、租赁表外、合并少数股东是本课序剩下三课，专门修口径。后课默认：提到任何基本面因子，都能指回表、字段、PIT 与宇宙；无法指回的，不当作可复制信号。</p><p>后三课只修正口径：分部改暴露，租赁改资产与负债，NCI 改要求权层。索引本身——价值来自账面、盈利来自利润表、投资来自资产变化、质量来自应计——不再改名。无法指回来源卡的信号，后课默认不当作可复制因子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HML 来自账面（表）对市值（价量），六月滞后是构造的一部分。</li><li>盈利来自利润表流量；投资来自资产或资本开支变化；质量来自应计差。</li><li>名字相同可以来源不同；来源卡先于分位断点。</li><li>同一并购可同时推动价值、投资与质量，共线要能指回字段。</li><li>后三课只修正口径，不改这张索引。</li><li>出处：Fama and French (1993, 2015)；Hou, Xue and Zhang (2015)；French 数据库构造说明。</li></ul>',8))])}const _=s(p,[["render",c]]);export{f as __pageData,_ as default};
